   // Presale contract structure (Solidity)
   pragma solidity ^0.8.0;

   import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
   import "@openzeppelin/contracts/access/Ownable.sol";
   import "@openzeppelin/contracts/utils/Counters.sol";

   contract PresaleContract is ERC20, Ownable {
       using Counters for Counters.Counter;

       // Define a counter to keep track of presale rounds
       Counters.Counter private _roundIDs;

       struct PresaleRound {
           uint256 startTime;
           uint256 endTime;
           uint256 tokenPrice;
           address[] whitelist;
       }

       // mapping of round ID to PresaleRound details
       mapping(uint256 => PresaleRound) private _presaleRounds;

       event PresaleRoundCreated(uint256 roundID, uint256 startTime, uint256 endTime, uint256 tokenPrice);
       event PresaleRoundWhitelistAdded(uint256 roundID, address[] whitelist);
       event PresaleTokenPurchased(address buyer, uint256 roundID, uint256 purchasedTokens);

       // Functions for managing presale rounds and adding whitelist addresses
       function createPresaleRound(uint256 _startTime, uint256 _endTime, uint256 _tokenPrice) external onlyOwner {
           _roundIDs.increment();
           uint256 roundID = _roundIDs.current();

           _presaleRounds[roundID] = PresaleRound(_startTime, _endTime, _tokenPrice, new address[](0));

           emit PresaleRoundCreated(roundID, _startTime, _endTime, _tokenPrice);
       }

       function addPresaleRoundWhitelist(uint256 _roundID, address[] memory _whitelist) external onlyOwner {
           require(_roundID <= _roundIDs.current(), "Invalid presale round ID");
           _presaleRounds[_roundID].whitelist = _whitelist;

           emit PresaleRoundWhitelistAdded(_roundID, _whitelist);
       }

       // Function to buy tokens during a presale round
       function buyPresaleTokens(uint256 _roundID) external payable {
           require(block.timestamp >= _presaleRounds[_roundID].startTime && block.timestamp <= _presaleRounds[_roundID].endTime, "Presale round not active");
