           uint256 purchasedTokens = _totalTokensToBuy;
           _mint(msg.sender, purchasedTokens);
           _presaleRounds[_roundID].whitelist.push(msg.sender);

           emit PresaleTokenPurchased(msg.sender, _roundID, purchasedTokens);
       }

       // Function to retrieve the presale round details
       function getPresaleRoundDetails(uint256 _roundID) public view returns (uint256, uint256, uint256, address[]) {
           require(_roundID <= _roundIDs.current(), "Invalid presale round ID");
           return (_presaleRounds[_roundID].startTime, _presaleRounds[_roundID].endTime, _presaleRounds[_roundID].tokenPrice, _presaleRounds[_roundID].whitelist);
       }
